import Setting from "@/setting";
import { diyGetInfo, diySave, getColorChange } from "@/api/diy";
import { mapState } from "vuex";
import editFrom from "@/components/from/from";
import {
  groupAllApi,
  groupDataListApi,
  groupSaveApi,
  groupDataAddApi,
  groupDataHeaderApi,
  groupDataEditApi,
  groupDataSetApi,
  getAgreement,
  setAgreement,
  openAdvSave,
  getOpenAdv,
} from "@/api/system";
import draggable from "vuedraggable";
import uploadPictures from "@/components/uploadPictures";
import linkaddress from "@/components/linkaddress";

export default {
  name: "list",
  components: { editFrom, draggable, uploadPictures, linkaddress },
  computed: {
    labelWidth() {
      return this.isMobile ? undefined : 120;
    },
    labelPosition() {
      return this.isMobile ? "top" : "right";
    },
    ...mapState("admin/layout", ["menuCollapse", "isMobile"]),
  },
  data() {
    return {
      formValidate: {
        content: "",
      },
      ruleValidate: {},
      agreementType: 0, //判断的隐私协议
      bgimg: 0,
      columns1: [],
      bgCol: "",
      name: "routine_home_bast_banner",
      grid: {
        xl: 7,
        lg: 7,
        md: 12,
        sm: 24,
        xs: 24,
      },
      loading: false,
      sginList: [],
      swiperOption: {
        //显示分页
        pagination: {
          el: ".swiper-pagination",
        },
        //设置点击箭头
        navigation: {
          nextEl: ".swiper-button-next",
          prevEl: ".swiper-button-prev",
        },
        //自动轮播
        autoplay: {
          delay: 2000,
          //当用户滑动图片后继续自动轮播
          disableOnInteraction: false,
        },
        //开启循环模式
        loop: false,
      },
      url: "",
      BaseURL: Setting.apiBaseURL.replace(/adminapi/, ""),
      pageId: 0,
      theme3: "light",
      tabList: {
        list: [],
      },
      lastObj: {
        add_time: "",
        comment: "",
        gid: "",
        id: "",
        img: "",
        link: "",
        sort: "",
        status: 1,
      },
      isChoice: "单选",
      modalPic: false,
      gridPic: {
        xl: 6,
        lg: 8,
        md: 12,
        sm: 12,
        xs: 12,
      },
      gridBtn: {
        xl: 4,
        lg: 8,
        md: 8,
        sm: 8,
        xs: 8,
      },
      groupAll: [],
      activeIndex: 0,
      sortName: null,
      activeIndexs: 0,
      cmsList: [],
      loadingExist: false,
      formItem: {
        time: 0,
        interval_time: 0,
        type: "pic",
        status: 1,
        value: [],
        video_link: "",
      },
    };
  },
  mounted() {
    this.info();
    this.url =
      this.BaseURL + "pages/columnGoods/HotNewGoods/index?type=1&name=精品推荐";
  },
  methods: {
    getEditorContent(data) {
      this.formValidate.content = data;
    },
    linkUrl(e) {
      this.tabList.list[this.activeIndexs].link = e;
    },
    info() {
      getOpenAdv().then((res) => {
        res.data.status = parseInt(res.data.status);
        this.formItem = res.data;
        this.tabList.list = res.data.value;
      });
    },
    addBox() {
      if (this.tabList.list.length == 5) {
        this.$Message.warning("最多添加五张呦");
      } else {
        this.$nextTick(() => {
          this.tabList.list.push({
            add_time: "",
            comment: "",
            gid: "",
            id: "",
            img: "",
            link: "",
            sort: "",
            status: 1,
          });
        });
      }
    },
    // 删除
    bindDelete(item, index) {
      this.tabList.list.splice(index, 1);
    },
    // 点击图文封面
    modalPicTap(title, index) {
      this.activeIndex = index;
      this.modalPic = true;
    },
    // 获取图片信息
    getPic(pc) {
      this.$nextTick(() => {
        this.tabList.list[this.activeIndex].img = pc.att_dir;
        this.modalPic = false;
      });
    },
    save() {
      this.formItem.value = this.tabList.list;
      openAdvSave(this.formItem)
        .then((res) => {
          this.loadingExist = false;
          this.$Message.success(res.msg);
        })
        .catch((err) => {
          this.loadingExist = false;
          this.$Message.error(err.msg);
        });
    },
    link(index) {
      this.activeIndexs = index;
      this.$refs.linkaddres.modals = true;
    },
  },
};
